  { q: 'Remote AI internship 2026 open applications', category: 'internship' },
  { q: 'site:linkedin.com/jobs AI ML internship Egypt 2026', category: 'internship' },
  // Training programs
  { q: 'DEPI digital egypt pioneers initiative 2026 AI track apply', category: 'training' },
  { q: 'ITI summer training 2026 AI machine learning Egypt', category: 'training' },
  { q: 'NTI training program 2026 Egypt artificial intelligence', category: 'training' },
