  { q: 'global AI hackathon online 2026 open to all countries', category: 'hackathon' },
  { q: 'Kaggle competition 2026 active AI machine learning', category: 'hackathon' },
  { q: 'student innovation challenge AI competition 2026 apply', category: 'hackathon' },
  { q: 'Arab region AI competition hackathon 2026', category: 'hackathon' }
];
return queries.map(q => ({ json: q }));

const items = $input.all();
const output = [];

const closedKeywords = [
  'closed', 'expired', 'deadline passed', 'no longer accepting', 'position filled',
  'applications closed', 'ended', 'over', 'not accepting', 'fully booked'
];

for (const item of items) {
  const category = item.json.category || 'internship';
  const results = item.json.organic_results || [];
  for (const r of results.slice(0, 5)) {
    const text = ((r.title || '') + ' ' + (r.snippet || '')).toLowerCase();
    const isClosed = closedKeywords.some(k => text.includes(k));
    if (isClosed) continue;
    output.push({
      json: {
        category,
        title: r.title || '',
        link: r.link || '',
        snippet: r.snippet || '',
        source: r.source || ''
      }
    });
  }
}

return output;

const raw = $input.first().json.results || [];

const closedKeywords = ['closed','expired','deadline passed','no longer accepting','position filled','applications closed','not accepting','fully booked'];

const seenTitles = new Set();
const seenLinks = new Set();
const cleaned = { internship: [], training: [], hackathon: [] };
const caps = { internship: 10, training: 5, hackathon: 5 };

for (const item of raw) {
  const cat = item.category || 'internship';
  if (!cleaned[cat]) continue;
  if (cleaned[cat].length >= caps[cat]) continue;

  const titleNorm = (item.title || '').toLowerCase().trim();
  const link = (item.link || '').trim();
  if (seenTitles.has(titleNorm) || seenLinks.has(link)) continue;

  const text = titleNorm + ' ' + (item.snippet || '').toLowerCase();
  if (closedKeywords.some(k => text.includes(k))) continue;

  seenTitles.add(titleNorm);
  if (link) seenLinks.add(link);

  cleaned[cat].push({
    title: item.title || '',
    link,
    snippet: (item.snippet || '').slice(0, 120),
    source: item.source || ''
  });
}

return [{ json: { internships: cleaned.internship, training: cleaned.training, hackathons: cleaned.hackathon } }];
